def solve(a):
    l,r=0,len(a)-1
    lm=rm=out=0
    while l<=r:
        if lm<=rm:
            lm=max(lm,a[l])
            out+=lm-a[l]
            l+=1
        else:
            rm=max(rm,a[r])
            out+=rm-a[r]
            r-=1
    return out
